// cuBLAS's level-3 routines and extensions: the line each prints on stdout for its first bad argument and the status,
// against an RTX 3060's cuBLAS 13.0 (card_edges_blas2.cu has gemv, the level-2 routines and the plain GEMMs).
//
//   - ?symm/?hemm, ?syrk/?herk, ?syr2k/?her2k, ?syrkx/?herkx, ?trsm, ?trmm, ?geam (and _64), ?dgmm, the batched GEMMs
//     and ?trsmBatched print " ** On entry to SSYMM  parameter number 7 had an illegal value" and return
//     INVALID_VALUE; the simulator returned the status and printed nothing. Positions are reference BLAS's (cuBLAS's
//     own extensions number their arguments the same way, the handle not counted); the batched GEMMs count as ?GEMM
//     with the batch count 14th (their strides are not counted) and ?trsmBatched as ?TRSM with it 12th. The fields
//     are the card's, odd ones and all: "SSYRK " for cublasSsyrkx, "STRMM"/"CTRMM" with no blank but "DTRMM ",
//     "SgemmStridedBatched", "SBATCHED TRSM ", "Cgemm3mBatched".
//   - cublasGemmEx and its batched and _64 forms print "GEMM_EX " with their own positions (lda 9, ...), and refuse an
//     algorithm outside CUBLAS_GEMM_DEFAULT..ALGO23 and DEFAULT_TENSOR_OP..ALGO15_TENSOR_OP (the simulator ran it);
//     cublasSgemmEx, cublasCgemmEx and cublasCgemm3mEx print "SGEMM_EX ", "CGEMM_EX " and "CGEMM " at ?GEMM's
//     positions, the Ex herk/syrk forms "CHERK ", "CSYRK ", "CSYRK3M " at ?HERK's.
//   - a transpose of T or C is taken by every herk/syrk form; only an unknown operation (CONJG among them) is refused.
// Not imitated, so not checked: the card's answers for an unknown data or compute type in the Ex routines (7 for some,
// 15 for others), GemmBatchedEx with a negative batch count (13), and strides that reach outside the buffers.
#include <cublas_v2.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

static int fails = 0;
#define WANT(x, want) do { const long long got_ = static_cast<long long>(x); if (got_ != static_cast<long long>(want)) { \
  std::printf("FAIL %s -> %lld, expected %lld\n", #x, got_, static_cast<long long>(want)); ++fails; } } while (0)

// Runs f with stdout going to a pipe and returns what it printed.
template <class F>
static std::string printed(F f, int* status) {
  std::fflush(stdout);
  int p[2];
  if (pipe(p) != 0) return "<pipe failed>";
  const int saved = dup(1);
  dup2(p[1], 1);
  *status = static_cast<int>(f());
  std::fflush(stdout);
  dup2(saved, 1);
  close(saved);
  close(p[1]);
  std::string out;
  char buf[4096];
  for (ssize_t n; (n = read(p[0], buf, sizeof buf)) > 0;) out.append(buf, static_cast<size_t>(n));
  close(p[0]);
  return out;
}

static std::string line(const char* field, int param) {
  char b[160];
  std::snprintf(b, sizeof b, " ** On entry to %s parameter number %d had an illegal value\n", field, param);
  return b;
}

// One refused (or accepted) call: its status and the line it prints, if any (field null: none).
#define CASE(label, want_status, field, param, call) do { int st_ = -1; \
  const std::string got_ = printed([&] { return (call); }, &st_); \
  const std::string want_ = (field) ? line((field), (param)) : std::string(); \
  if (st_ != static_cast<int>(want_status) || got_ != want_) { ++fails; \
    std::printf("FAIL %s: status %d, expected %d; printed \"%s\", expected \"%s\"\n", label, st_, \
                static_cast<int>(want_status), got_.c_str(), want_.c_str()); } } while (0)

static const char* const kNone = nullptr;

int main() {
  cublasHandle_t h;
  WANT(cublasCreate(&h), CUBLAS_STATUS_SUCCESS);
  const size_t bytes = 1 << 16;
  void *vA = nullptr, *vB = nullptr, *vC = nullptr, *vX = nullptr;
  for (void** p : {&vA, &vB, &vC, &vX}) {
    WANT(cudaMalloc(p, bytes), cudaSuccess);
    WANT(cudaMemset(*p, 0, bytes), cudaSuccess);
  }
  // Two matrices per batch, as device arrays of pointers.
  void** arrays[3] = {nullptr, nullptr, nullptr};
  void* const bases[3] = {vA, vB, vC};
  for (int i = 0; i < 3; ++i) {
    void* host[2] = {bases[i], static_cast<char*>(bases[i]) + 4096};
    WANT(cudaMalloc(&arrays[i], sizeof host), cudaSuccess);
    WANT(cudaMemcpy(arrays[i], host, sizeof host, cudaMemcpyHostToDevice), cudaSuccess);
  }
  const double one[2] = {1, 0};   // alpha and beta, read as each type wants them
#define VGPU_TYPED(p, T)                                                                                    \
  const T* p##al = reinterpret_cast<const T*>(one);                                                         \
  T *p##A = static_cast<T*>(vA), *p##B = static_cast<T*>(vB), *p##C = static_cast<T*>(vC);                   \
  const T* const* p##Aa = reinterpret_cast<const T* const*>(arrays[0]);                                     \
  const T* const* p##Ba = reinterpret_cast<const T* const*>(arrays[1]);                                     \
  T* const* p##Ca = reinterpret_cast<T* const*>(arrays[2]);
#define VGPU_TYPED_X(p, T)                                                                                  \
  VGPU_TYPED(p, T)                                                                                          \
  T* p##X = static_cast<T*>(vX);                                                                            \
  T* const* p##Bo = reinterpret_cast<T* const*>(arrays[1]);   /* trsmBatched's B */
  VGPU_TYPED_X(s, float)
  VGPU_TYPED_X(d, double)
  VGPU_TYPED_X(c, cuComplex)
  VGPU_TYPED_X(z, cuDoubleComplex)
  VGPU_TYPED(h, __half)
#undef VGPU_TYPED_X
#undef VGPU_TYPED
  const void* const* vAa = reinterpret_cast<const void* const*>(arrays[0]);
  const void* const* vBa = reinterpret_cast<const void* const*>(arrays[1]);
  void* const* vCa = reinterpret_cast<void* const*>(arrays[2]);
  const auto N = CUBLAS_OP_N;
  const auto SL = CUBLAS_SIDE_LEFT;
  const auto LO = CUBLAS_FILL_MODE_LOWER;
  const auto ND = CUBLAS_DIAG_NON_UNIT;
  const auto BadSide = static_cast<cublasSideMode_t>(99);
  const auto BadFill = static_cast<cublasFillMode_t>(99);
  const auto BadOp = static_cast<cublasOperation_t>(99);
  const auto Conjg = static_cast<cublasOperation_t>(3);   // CUBLAS_OP_CONJG
  const auto BadDiag = static_cast<cublasDiagType_t>(99);
  const auto BadAlgo = static_cast<cublasGemmAlgo_t>(-5);

  // Generated from a run on the card: every bad argument of the S and C forms, the first of the D and Z forms
  // (which only differ in their field), and the call with every argument good.
  CASE("cublasSsymm_v2 1 side 99", 7, "SSYMM ", 1, cublasSsymm_v2(h,BadSide,LO,4,4,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 2 uplo 99", 7, "SSYMM ", 2, cublasSsymm_v2(h,SL,BadFill,4,4,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 2 uplo CUBLAS_FILL_MODE_FULL", 7, "SSYMM ", 2, cublasSsymm_v2(h,SL,CUBLAS_FILL_MODE_FULL,4,4,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 3 m -1", 7, "SSYMM ", 3, cublasSsymm_v2(h,SL,LO,-1,4,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 4 n -1", 7, "SSYMM ", 4, cublasSsymm_v2(h,SL,LO,4,-1,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 7 lda 1", 7, "SSYMM ", 7, cublasSsymm_v2(h,SL,LO,4,4,sal,sA,1,sB,4,sal,sC,4));
  CASE("cublasSsymm_v2 9 ldb 1", 7, "SSYMM ", 9, cublasSsymm_v2(h,SL,LO,4,4,sal,sA,4,sB,1,sal,sC,4));
  CASE("cublasSsymm_v2 12 ldc 1", 7, "SSYMM ", 12, cublasSsymm_v2(h,SL,LO,4,4,sal,sA,4,sB,4,sal,sC,1));
  CASE("cublasSsymm_v2 ok", 0, kNone, 0, cublasSsymm_v2(h,SL,LO,4,4,sal,sA,4,sB,4,sal,sC,4));
  CASE("cublasDsymm_v2 1 side 99", 7, "DSYMM ", 1, cublasDsymm_v2(h,BadSide,LO,4,4,dal,dA,4,dB,4,dal,dC,4));
